            if diffCol == diffRow {
                ret false;
            }
        }
        ret true;
    }

    fn solve(row: Int) -> Void {
        if row == self.n {
            self.count = self.count + 1;
            ret;
        }
        loop col in 0..self.n {
            if self.isSafe(row, col) {
                self.cols[row] = col;
                self.solve(row + 1);
            }
        }
        ret;
    }
}

